package com.example.appanh;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.RecyclerView;
import com.bumptech.glide.Glide;
import com.example.appanh.models.*;
import java.util.*;
public final class MediaAdapter extends RecyclerView.Adapter<MediaAdapter.Holder> {
 public interface Events { void tap(Object item); void hold(Object item); }
 private List<?> items; private final GalleryRepository repo; private final Set<String> selected; private final Events events; private final boolean rows;
 private final Map<String,Integer> selectionOrder=new LinkedHashMap<>();
 public MediaAdapter(List<?> items,GalleryRepository repo,Set<String> selected,Events events,boolean rows){this.items=items;this.repo=repo;this.selected=selected;this.events=events;this.rows=rows;int number=1;for(String id:selected)selectionOrder.put(id,number++);}
 public void update(List<?> next){items=next;selectionOrder.clear();int number=1;for(String id:selected)selectionOrder.put(id,number++);notifyDataSetChanged();}
 @Override public Holder onCreateViewHolder(ViewGroup parent,int type){return new Holder(LayoutInflater.from(parent.getContext()).inflate(type==1?R.layout.item_album:type==2?R.layout.item_media_row:R.layout.item_media,parent,false));}
 @Override public void onBindViewHolder(Holder h,int position){Object item=items.get(position);Object image=null;String caption,id;
  if(item instanceof Photo){Photo p=(Photo)item;image=repo.source(p);id=p.getId();caption=(p.isVideo()?"▶  Video":"")+(p.isFavorite()?"  ♥":"");if(rows)caption=p.getFileName()+"\n"+com.example.appanh.helpers.PhotoHelper.formatFileSize(p.getFileSize());h.image.setContentDescription(p.getFileName());}
  else{Album a=(Album)item;id=a.getId();if(a.getCoverPhotoPath()!=null&&new java.io.File(a.getCoverPhotoPath()).exists())image=new java.io.File(a.getCoverPhotoPath());else if(a.getCoverPhotoUrl()!=null&&!a.getCoverPhotoUrl().isEmpty())image=a.getCoverPhotoUrl();for(Photo p:repo.photos)if((p.isDeleted()||p.isHidden())&&((p.getFilePath()!=null&&Objects.equals(p.getFilePath(),a.getCoverPhotoPath()))||(p.getFirebaseUrl()!=null&&Objects.equals(p.getFirebaseUrl(),a.getCoverPhotoUrl()))))image=null;int images=0,videos=0;for(Photo p:repo.photos)if(!p.isDeleted()&&!p.isHidden()&&p.getAlbumIds().contains(a.getId())){if(image==null)image=repo.source(p);if(p.isVideo())videos++;else images++;}caption=a.getName()+"\n"+(images==0&&videos>0?videos+" video":videos==0?images+" ảnh":images+" ảnh · "+videos+" video");View badge=h.itemView.findViewById(R.id.albumVideoBadge);if(badge!=null)badge.setVisibility(videos>0?View.VISIBLE:View.GONE);View more=h.itemView.findViewById(R.id.albumMore);if(more!=null){more.setContentDescription("Tùy chọn album "+a.getName());more.setOnClickListener(view->events.hold(item));}}
  Glide.with(h.image).load(image).signature(new com.bumptech.glide.signature.ObjectKey(image instanceof java.io.File?((java.io.File)image).lastModified()+":"+((java.io.File)image).length():"remote")).placeholder(R.drawable.art_landscape).error(R.drawable.ic_photo).centerCrop().into(h.image);h.caption.setText(caption);if(item instanceof Album){android.text.SpannableString styled=new android.text.SpannableString(caption);int newline=caption.indexOf('\n');styled.setSpan(new android.text.style.StyleSpan(android.graphics.Typeface.BOLD),0,newline,0);styled.setSpan(new android.text.style.ForegroundColorSpan(h.itemView.getContext().getColor(R.color.text_secondary)),newline+1,caption.length(),0);styled.setSpan(new android.text.style.RelativeSizeSpan(.85f),newline+1,caption.length(),0);h.caption.setText(styled);}h.caption.setVisibility(caption.trim().isEmpty()?View.GONE:View.VISIBLE);boolean chosen=selected.contains(id);h.check.setVisibility(chosen?View.VISIBLE:View.GONE);if(h.check instanceof TextView){((TextView)h.check).setText(chosen?String.valueOf(selectionOrder.get(id)):"");h.check.setContentDescription(chosen?"Đã chọn thứ "+selectionOrder.get(id):null);}if(item instanceof Photo&&h.itemView instanceof com.google.android.material.card.MaterialCardView){com.google.android.material.card.MaterialCardView card=(com.google.android.material.card.MaterialCardView)h.itemView;card.setStrokeWidth(chosen?(int)(2*card.getResources().getDisplayMetrics().density):0);card.setStrokeColor(card.getContext().getColor(R.color.button_primary));}h.itemView.setOnClickListener(v->events.tap(item));h.itemView.setOnLongClickListener(v->{events.hold(item);return true;});
 }
 @Override public int getItemViewType(int position){return items.get(position) instanceof Album?1:rows?2:0;}
 @Override public int getItemCount(){return items.size();}
 static final class Holder extends RecyclerView.ViewHolder {final ImageView image;final TextView caption;final View check;Holder(View view){super(view);image=view.findViewById(R.id.thumbnail);caption=view.findViewById(R.id.caption);check=view.findViewById(R.id.check);}}
}
